import math

def check_condition(n):
    """Checks if k^2 === 1 (mod n) for all k coprime to n."""
    if n < 2:
        return False

    print(f"--- Checking n = {n} ---")
    is_valid = True

    # Iterate through k from 1 up to n-1
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # k is coprime to n, check the condition
            if (k * k) % n != 1:
                print(f"Counterexample found for n={n}: k={k}. {k}^2 = {k*k}. {k*k} mod {n} = {(k*k) % n}, not 1.")
                is_valid = False
                break

    if is_valid:
        print(f"Condition holds true for n = {n}.")
    return is_valid

